import {
    Component,
    OnDestroy,
    OnInit,
    ViewChild,
    ElementRef,
} from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { ProfileService } from '../profile.service';
import { Subscription } from 'rxjs';
import { UserService } from 'src/app/_services/user.service';
import { ConfirmationService } from 'primeng/api';

@Component({
    selector: 'change-username',
    templateUrl: './change-username.component.html',
    styleUrls: ['./change-username.component.scss'],
})
export class ChangeUsernameComponent implements OnInit, OnDestroy {
    @ViewChild('username') username: ElementRef;

    constructor(
        private userService: UserService,
        private profileService: ProfileService,
        private confirmationService: ConfirmationService
    ) {}

    loggedInUser = this.userService.loggedInUser;
    userDialogVisible;
    loading;
    subscriptions = new Subscription();
    submitted: boolean = false;

    ngOnInit(): void {
        this.subscriptions.add(
            this.profileService.userDialogVisible.subscribe((res) => {
                this.userDialogVisible = res;
            })
        );
        this.subscriptions.add(
            this.profileService.loading.subscribe((res) => {
                this.loading = res;
            })
        );
        this.subscriptions.add(
            this.profileService.existedUsernameError.subscribe(() => {
                this.username.nativeElement.select();
                this.userForm.controls['new_username'].setErrors({
                    error: 'Username already exists',
                });
            })
        );
    }
    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // open or close user dialog
    toggleUserDialog(value: boolean) {
        this.profileService.userDialogVisible.next(value);
    }
    // username form
    userForm = new FormGroup({
        new_username: new FormControl(null, Validators.required),
    });
    get new_username() {
        return this.userForm.get('new_username');
    }

    // submit username
    submitUsername() {
        this.submitted = true;
        if (this.userForm.valid) {
            this.confirmationService.confirm({
                key: 'profile',
                message: `Are you sure that you want to update username to "${this.new_username.value}"?`,
                header: 'Warning',
                icon: 'pi pi-exclamation-triangle',
                acceptButtonStyleClass: 'p-button-danger',
                rejectButtonStyleClass: 'p-button-secondary',
                defaultFocus: 'reject',
                accept: () => {
                    this.profileService.loading.next(true);
                    this.profileService.updateUsername(this.userForm.value);
                },
                reject: () => {
                    this.submitted = false;
                },
            });
        }
    }

    // reset form dialog
    resetDialog() {
        this.submitted = false;
        this.userForm.reset();
        this.profileService.loading.next(false);
        this.profileService.userDialogVisible.next(false);
    }
}
