import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ApiService } from 'src/app/_services/api.service';
import { TokenStorageService } from '../_services/token-storage.service';
import { UserService } from '../_services/user.service';
import { BehaviorSubject, Subject } from 'rxjs';

@Injectable({
    providedIn: 'root',
})
export class ProfileService {
    constructor(
        private http: HttpClient,
        private notificationService: NotificationsService,
        private api: ApiService,
        private tokenStorage: TokenStorageService,
        private userService: UserService
    ) {}

    private host = this.api.host;

    userDialogVisible = new BehaviorSubject<boolean>(false);
    passDialogVisible = new BehaviorSubject<boolean>(false);
    loading = new BehaviorSubject<boolean>(false);
    existedUsernameError = new Subject<void>();

    oldPasswordError = new Subject<void>();

    // update username
    updateUsername(username) {
        this.http.put<any>(`${this.host}/profile`, username).subscribe({
            next: (res) => {
                this.tokenStorage.saveUser(res.username);
                this.tokenStorage.saveToken(res.token);
                this.userService.loggedInUser.set(res.username);
                this.notificationService.showSuccess(
                    'Username updated successfully!',
                    'profile'
                );
            },
            error: (error: HttpErrorResponse) => {
                if (error.status == 406) {
                    this.existedUsernameError.next();
                } else {
                    this.notificationService.handleError(error, 'profile');
                }
                this.loading.next(false);
            },
            complete: () => {
                this.userDialogVisible.next(false);
                this.loading.next(false);
            },
        });
    }

    // update password
    updatePassword(passwords) {
        this.http
            .put<any>(`${this.host}/profile/password`, passwords)
            .subscribe({
                next: (res) => {
                    console.log(res);
                    this.notificationService.showSuccess(
                        res.message,
                        'profile'
                    );
                },
                error: (error: HttpErrorResponse) => {
                    if (error.status == 406) {
                        // old password incorrect, server will send code 406 (Not Acceptable)
                        console.log(error.error.message);
                        this.oldPasswordError.next();
                    } else {
                        this.notificationService.handleError(error, 'profile');
                    }
                    this.loading.next(false);
                },
                complete: () => {
                    this.passDialogVisible.next(false);
                    this.loading.next(false);
                },
            });
    }
}
