import {
    Component,
    ElementRef,
    OnDestroy,
    OnInit,
    ViewChild,
} from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { ProfileService } from '../profile.service';
import { Subscription } from 'rxjs';
import { UserService } from 'src/app/_services/user.service';
import { ConfirmationService } from 'primeng/api';

@Component({
    selector: 'change-password',
    templateUrl: './change-password.component.html',
    styleUrls: ['./change-password.component.scss'],
})
export class ChangePasswordComponent {
    @ViewChild('currentPassword') currentPassword: ElementRef;

    constructor(
        private userService: UserService,
        private profileService: ProfileService,
        private confirmationService: ConfirmationService
    ) {}

    loggedInUser = this.userService.loggedInUser;
    passDialogVisible;
    loading;
    subscriptions = new Subscription();
    submitted: boolean = false;
    oldPasswordError: boolean = false;

    ngOnInit(): void {
        this.subscriptions.add(
            this.profileService.passDialogVisible.subscribe((res) => {
                this.passDialogVisible = res;
            })
        );
        this.subscriptions.add(
            this.profileService.loading.subscribe((res) => {
                this.loading = res;
            })
        );
        this.subscriptions.add(
            this.profileService.oldPasswordError.subscribe(() => {
                this.currentPassword.nativeElement.select();
                this.oldPasswordError = true;
                this.passForm.controls['current_password'].setErrors({
                    error: 'Old password is incorrect!',
                });
            })
        );
    }
    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // open or close user dialog
    togglePassDialog(value: boolean) {
        this.profileService.passDialogVisible.next(value);
    }

    // password form
    passForm = new FormGroup({
        current_password: new FormControl(null, Validators.required),
        new_password: new FormControl(null, [Validators.required]),
        confirm_password: new FormControl(null, [Validators.required]),
    });
    get current_password() {
        return this.passForm.get('current_password');
    }
    get new_password() {
        return this.passForm.get('new_password');
    }
    get confirm_password() {
        return this.passForm.get('confirm_password');
    }

    // submit password
    submitPassword() {
        // console.log(this.confirm_password.invalid);

        this.submitted = true;
        if (this.passForm.valid) {
            if (
                this.passForm.value.new_password ==
                this.passForm.value.confirm_password
            ) {
                this.confirmationService.confirm({
                    key: 'profile',
                    message: `Are you sure that you want to continue ?`,
                    header: 'Warning',
                    icon: 'pi pi-exclamation-triangle',
                    acceptButtonStyleClass: 'p-button-danger',
                    rejectButtonStyleClass: 'p-button-secondary',
                    defaultFocus: 'reject',
                    accept: () => {
                        this.profileService.loading.next(true);
                        this.profileService.updatePassword(this.passForm.value);
                    },
                    reject: () => {
                        this.submitted = false;
                    },
                });
            } else {
                this.passForm.controls['new_password'].setErrors({
                    error: 'password didnt match!',
                });
                this.passForm.controls['confirm_password'].setErrors({
                    error: 'password didnt match!',
                });
            }
        }
    }

    // reset form dialog
    resetDialog() {
        this.submitted = false;
        this.passForm.reset();
        this.profileService.loading.next(false);
        this.profileService.passDialogVisible.next(false);
    }

    // fire error on old password input
    currentPasswordError() {
        this.passForm.controls['current_password'].setErrors({
            error: 'old password is incorrect!',
        });
    }
}
